parameters.jsonBody:
={{ JSON.stringify({
  contents: [{
    parts: [{
      text: `You are a creative director for a print-on-demand brand.

Here is a trend analysis report:
${JSON.stringify($json.trendAnalysis ? JSON.parse($json.trendAnalysis) : $json, null, 2)}

Generate EXACTLY 10 original t-shirt design concepts. Each must be:
- Unique and non-overlapping
- Targeting a specific audience segment
- Based on real trends from the data
- Print-ready (clear hierarchy, limited colors)

Return ONLY a JSON array of 10 objects. No markdown.
Shape per object:
{
  "id": 1,
  "title": "",
  "concept": "",
  "targetAudience": "",
  "sellingAngle": "",
  "tone": "motivational|ironic|raw|minimalist|bold",
  "phrase": "",
  "imagePrompt": "",
  "colors": [],
  "typography": "",
  "icons": []
}`
    }]
  }],
  generationConfig: { temperature: 0.8, maxOutputTokens: 3000 }
}) }}

parameters.jsCode:
const raw = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text || '[]';
const match = raw.match(/\[[\s\S]*\]/);
let concepts = [];
try { concepts = JSON.parse(match?.[0] || '[]'); } catch (_) {}

const trendAnalysisRaw = $('Execute Workflow Trigger').first().json.trendAnalysis || '{}';
let niche = '';
try { niche = JSON.parse(trendAnalysisRaw).niche || ''; } catch (_) {}

return [{ json: { niche, concepts } }];
